(window.BIB_BOOKS=window.BIB_BOOKS||{})["TIT"]={"chapters":[["פולוס עבד אלהים ושליח ישוע המשיח לפי אמונת בחירי אלהים ודעת האמת אשר לחסידות׃","עלי תקות חיי העולם אשר הבטיח לפני ימות עולם האל אשר לא ישקר׃","וגלה במועדו את דברו על ידי הקריאה המפקדה בידי על פי מצות האלהים מושיענו׃","אל טיטוס בנו האמתי לפי אמונה אחת חסד ורחמים ושלום מאת האלהים אבינו ואדנינו ישוע המשיח מושיענו׃","לזאת עזבתיך בקריטי למען תשלים את החסד ותשים זקנים בכל עיר ועיר כאשר צויתיך׃","אם ימצא איש תם ובעל אשה אחת ויש לו בנים מאמינים ואין עליהם טענת פריצות ואינם סוררים׃","כי פקיד העדה צריך להיות איש תם כסכן לאלהים לא עמד על דעתו ולא רגזן ולא אהב יין ולא בעל אגרף ולא נטה אחרי הבצע׃","כי אם יהי מכניס ארחים ואהב טוב וצנוע וצדיק וקדוש וכבש את יצרו׃","ומחזיק בדבר הנאמן כפי ההוראה למען יהיה בכחו להזהיר בלקח הבריא ולהוכיח את המריבים׃","כי יש הרבה מרדים מדברי הבל ומתעי נפש ובפרט מן המולים׃","אשר סכור יסכר פיהם ההפכים בתים כלם בהורותם דברים לא כנים עקב בצע׃","וכבר אמר אחד מהם נביאם אשר בתוכם בני קריטי כזבים הם מעולם וחיות רעות וכרשים עצלים׃","והעדות הזאת אמת היא ובעבור כן תוכיחם תוכחה קשה למען יהיו בריאים באמונה׃","ולא ישימו לב אל הגדות היהודים ואל מצות האנשים הסרים מן האמת׃","הן הכל טהור לטהורים אבל לנטמאים ולאינם מאמינים אין דבר טהור כי נטמאה גם דעתם גם רוחם׃","אמרים המה כי ידעו את האלהים ובמעשיהם כופרים בו כי מתעבים וממרים הם ולא יצלחו לכל מעשה טוב׃"],["ואתה דבר את הנאה ללקח הבריא׃","שיהיו הזקנים משלים ברוחם ומכבדים וצנועים ובריאים באמונה ובאהבה ובסבלנות׃","וכן הזקנות תהי הנהגתן כאשר נאוה לקדש לא תהיינה מלשינות ולא נכבשות לסבוא יין כי אם מלמדות טוב׃","ומישרות את הצעירות לאהב את בעליהן ולאהב את בניהן׃","ולהיות צנועות וטהרות צופיות הליכות ביתן וטבות ונכנעות לבעליהן למען לא יחלל דבר האלהים׃","ככה תזהיר גם את הבחורים שיהיו צנועים׃","ובכל דבר היה אתה למופת במעשים טובים בהוראה צרופה ונהדרה׃","ובדבר בריא ומום אין בו למען יבוש המתקומם ולא ימצא לדבר עליכם רע׃","העבדים יכנעו לאדניהם ויתרצו להם בכל דבר ולא ימרו את דבריהם׃","ולא ימעלו מעל כי אם יראו כל אמונה טובה למען יפארו בכל את לקח אלהינו מושיענו׃","כי הופיע חסד אלהים להושיע את כל בני האדם׃","וליסר אתנו אשר נתעב הרשע ותאות העולם ונחיה בעולם הזה בצניעות ובצדק ובחסידות׃","ונחכה לתקוה המאשרת ולהופעת כבוד אלהינו הגדול ומושיענו ישוע המשיח׃","אשר נתן את נפשו בעדנו לגאלנו מכל עול ולטהר לו עם סגלה הזריז במעשים טובים׃","את אלה תדבר ותזהיר ותוכיח בכל חזקה ואיש אל יבוז לך׃"],["הזכר אתם להכנע ולשמע לשרים ולשלטונים ולהיות נכונים לכל מעשה טוב׃","ולבלתי גדף אדם ולחדל מריב ולהכריע לכף זכות ולהתנהג בכל ענוה לפני כל אדם׃","כי גם אנחנו היינו מלפנים חסרי דעת וסוררים ותועים ועבדים לתאות ולתשוקות שנות ומתהלכים ברשעה וקנאה ושנואים ושנאים איש את אחיו׃","אמנם כאשר נגלה נעם אלהים מושיענו ורחמנותו אל האדם׃","אז לא בגלל מעשי הצדקה אשר עשינו הושיע אתנו כי אם מתוך חסדו על ידי טבילת התולדה השניה וחדוש רוח הקדש׃","אשר שפך עלינו למכביר על ידי ישוע המשיח מושיענו׃","למען נצדק בחסדו ונירש לפי התקוה את חיי העולמים׃","נאמן הוא הדבר ורצה אני כי תקים את אלה למען אשר ישתדלו המאמינים לאלהים לעשק במעשים טובים עשות כאלה טוב הוא ומועיל לאדם׃","אבל תרחק מן השאלות התפלות ומלמודי תולדות ומן הקטטות ומחלקות בעניני החקים כי אין בהן מועיל והבל הנה׃","ואיש החולק על האמונה אם הוכח פעם ושתים שטה מעליו׃","ודע כי איש כזה איש תהפכות הוא וחוטא בהרשיע את נפשו׃","כאשר אשלח אליך את ארטמס או את טוכיקוס תמהר לבוא אלי לניקפליס כי גמרתי בלבי לשבת שם בימי הסתיו׃","השתדל ללות על דרכם את זינס המלמד בתורה ואת אפולוס למען לא יחסרו דבר׃","וילמדו גם אנשי עדתנו לעשק במעשים טובים לעזר בכל מחסור פן יהיו בלי פרי׃","כל אשר עמדי שאלים לשלומך שאל לשלום האהבים אתנו באמונה החסד עם כלכם אמן׃"]]};
